import { AttributeIcon } from "#core/ui-next/screens/create-game/attribute-icon.jsx";
import { TraditionItem } from "#core/ui-next/screens/create-game/civ-details.jsx";
import { useCivSelectModelContext } from "#core/ui-next/screens/create-game/civ-select-model.js";
import { useGameSetupModelContext } from "#core/ui-next/screens/create-game/create-game-setup-model.js";
import { CreateGameStage, CreateGameStageHeader } from "#core/ui-next/screens/create-game/create-game-stage.jsx";
import { useLeaderSelectModelContext } from "#core/ui-next/screens/create-game/leader-select-model.js";
import { useMementoSelectModelContext } from "#core/ui-next/screens/create-game/memento-select-model.js";
import { useRecommendedChoiceModelContext } from "#core/ui-next/screens/create-game/recommended-choice-model.js";
import { TicketBox } from "#core/ui-next/screens/create-game/ticket-box.jsx";
