export interface HubLayout {
	class?: string;
}

export const CreateGameHubLayout: ParentComponent = (props) => {
	const flowContext = useScreenFlowContext();

	return (
		<CreateGameStage
			header={
				<CreateGameStageHeader
					showSteps={false}
					title="LOC_UI_CREATE_GAME_OVERVIEW"
					exitText="LOC_MAIN_MENU_EXIT"
					onBack={() => {
						flowContext.clearHub();
						flowContext.activatePrev();
					}}
				/>
			}
		>
			<div
				class="font-title absolute inset-0"
				data-name="layout-center"
			>
				{props.children}
			</div>
			<div
				class="h-19"
				data-name="layout-footer"
			/>
		</CreateGameStage>
	);
};

// MARK: LEADER INFO
export const HubLeaderInfo: Component<HubLayout> = (props) => {
	const leaderModel = useLeaderSelectModelContext();
	const screenFlow = useScreenFlowContext();

	const leader = createMemo(() => leaderModel.selectedLeader());

	const rewardDesc = createMemo(() => {
		const reward = leader().nextReward;
		if (!reward) {
			return undefined;
		}

		// TODO: This should use a more robust lookup
		const rewardType = getRewardType(reward.gameItemID);
		return rewardType == UnlockableRewardType.Memento
			? `LOC_${reward.gameItemID}_FUNCTIONAL_DESCRIPTION`
			: undefined;
	});

	const leaderID = createMemo(() => leader().leaderID);

	const leaderImage = createMemo(() => Locale.toLower(leaderID()).replace("leader_", "lsl_"));

	const isAgeTransition = UI.isInGame();
	const isOfflineMemento = !Network.supportsSSO() && Online.Metaprogression.supportsMemento();

	const selectedLeaderTags = createMemo(() => leader().tags);
	const audio = useAudio("CreateGameHub");

	onMount(() => {
		audio("popup-open");
	});

	return (
		<div class={`flex flex-col mx-1 ${props.class ?? ""}`}>
			<div class="uppercase font-body text-accent-2 text-sm mb-1">
				<L10n.Compose text="LOC_CREATE_GAME_LEADER_SELECT_CATEGORY" />
			</div>
			<div class="relative">
				<Tooltip
					showFiligrees={leaderID() != "RANDOM"}
					initialHPosition={
						leaderID() != "RANDOM" ? TooltipHorizontalPosition.RIGHT : TooltipHorizontalPosition.CENTER
					}
					initialVPosition={
						leaderID() != "RANDOM" ? TooltipVerticalPosition.CENTER : TooltipVerticalPosition.BOTTOM
					}
				>
					<Tooltip.Trigger>
						<Activatable
							class="create-game-hub-banner relative group"
							onActivate={() => screenFlow.activate("leader-select")}
							disabled={isAgeTransition}
						>
							<div class="absolute inset-0 flex flex-col items-center justify-end">
								<div class="absolute inset-0 -top-0\.5 img-unit-panelbox pointer-events-none" />
								<Show when={leaderID() != "RANDOM"}>
									<div
										class="absolute inset-0"
										style={{
											background: "url('blp:CG_Leader_BG')",
											"background-size": "cover",
											"background-position": "center center",
										}}
									/>
									<div
										class="absolute inset-0"
										style={{
											"background-image": `url('blp:${leaderImage()}.png')`,
											"background-size": "cover",
											"background-position-x": "50%",
										}}
									/>
								</Show>
								<Show when={leaderID() == "RANDOM"}>
									<div
										class="absolute inset-0"
										style={{
											"background-image": `url('blp:CG_Leader_BG')`,
											"background-size": "cover",
											"background-position": "center center",
										}}
									/>
									<div
										class="absolute inset-0 create-game-hub-random-silhouette"
										style={{
											"background-image": `url(blp:shell_leader-silhouette.png)`,
											"background-size": "cover",
											"background-position": "center center",
										}}
									/>
								</Show>
								<div class="create-game-hub-bottom-gradient absolute left-0 bottom-0" />

								<div class="absolute inset-0 w-full h-full border-2 border-secondary-3" />
								<Show when={leaderID() != "RANDOM" && !isOfflineMemento}>
									<div class="create-game-hub-leader-level-bg relative flex items-center justify-center mb-9">
										<RingMeter
											class="leader-button-xp-ring min-size-28 size-28 m-8"
											value={leaderModel.selectedLeader().currentXp}
											min={leaderModel.selectedLeader().prevLevelXp}
											max={leaderModel.selectedLeader().nextLevelXp}
											ringImage={'url("blp:shell_leader-xp-ring.png")'}
										>
											<div class="font-body create-game-hub-leader-level flex items-center justify-center font-white">
												{leaderModel.selectedLeader().level}
											</div>
										</RingMeter>
									</div>
								</Show>
								<Show when={leaderID() == "RANDOM"}>
									<Icon
										class="size-22 mb-16 relative create-game-hub-random-icon"
										name={"LEADER_RANDOM"}
									/>
								</Show>
								<div class="img-rollover-highlight absolute inset-0 opacity-0 group-focus\:opacity-100 group-hover\:opacity-100 group-pressed\:opacity-100 pointer-events-none" />
							</div>
						</Activatable>
					</Tooltip.Trigger>
					<Tooltip.Content>
						<Tooltip.Frame class={"flex flex-col relative p-3 " + (leaderID() != "RANDOM" ? "w-96" : "")}>
							<Show when={leaderID() == "RANDOM"}>
								<div class="flex-auto p-3 img-base-ticket-bg">
									<L10n.Compose text={leader().name} />
								</div>
							</Show>
							<Show when={leaderID() != "RANDOM"}>
								<div class="flex flex-col relative justify-center items-center">
									<div class="uppercase text-tertiary-1 font-title uppercase">
										<L10n.Compose text={"LOC_UI_CREATE_GAME_LEADER_ABILITY"} />
									</div>
									<div class="flex flex-row flex-wrap items-center justify-start self-start gap-2 my-2">
										<For each={leader().tags}>
											{(attribute) => (
												<div class="flex flex-row items-center justify-start">
													<div class="create-game-civ-card-icon flex items-center justify-center gap-2">
														<Icon
															name={attribute
																.replace("LOC_TAG_TRAIT_", "ATTRIBUTE_")
																.replace("_NAME", "")}
															class={`relative size-8`}
															context="OUTLINE"
														/>
													</div>
													<div class="uppercase text-sm">
														<L10n.Compose text={attribute} />
													</div>
												</div>
											)}
										</For>
									</div>
									<TicketBox class="flex-auto flex flex-row relative mt-1">
										<div class="flex flex-col flex-auto ml-5">
											<div class="text-base font-title uppercase text-tertiary-1 mb-2">
												<L10n.Compose text={leader().abilityTitle} />
											</div>
											<div class="text-accent-5 text-sm">
												<L10n.Stylize
													class="create-game-markup"
													text={leader().abilityTextTag}
												/>
											</div>
										</div>
									</TicketBox>
								</div>
							</Show>
						</Tooltip.Frame>
					</Tooltip.Content>
				</Tooltip>
				<div class="absolute bottom-0\.5 w-full px-0\.5 flex justify-between">
					<For each={selectedLeaderTags()}>
						{(item) => (
							<div
								class="flex items-center justify-center size-12 ml-0\.5"
								style={{
									"background-image": "url(blp:hud_sub_circle_dis)",
									"background-repeat": "no-repeat",
									"background-size": "cover",
								}}
							>
								<AttributeIcon
									class="size-8 relative ml-0\.5 -mt-0\.5"
									attribute={item}
								/>
							</div>
						)}
					</For>
				</div>
			</div>
			<Show when={!isOfflineMemento}>
				<div class="flex flex-row items-center justify-center create-game-hub-trait-icon-container">
					<Show when={leader().nextReward?.reward}>
						<Tooltip>
							<Tooltip.Trigger>
								<AudioContextProvider segment="TraitIcon">
									<Activatable disableFocus={true}>
										<Icon
											class="size-9 create-game-hub-trait-icon"
											name={`url('${leader().nextReward?.reward}')`}
										/>
									</Activatable>
								</AudioContextProvider>
							</Tooltip.Trigger>
							<Tooltip.Content>
								<Tooltip.Frame class="flex flex-col relative w-128 p-3">
									<div class="flex flex-row justify-center">
										<div class="text-tertiary-1 font-title flex flex-row uppercase">
											<L10n.Compose text="LOC_UI_RADIAL_MENU_DETAILS_UNLOCK_NEXT" />
											{":"}
										</div>
										<div class="text-accent-2 ml-1 flex flex-row uppercase">
											<L10n.Compose
												text="LOC_END_GAME_ADD_LEVEL"
												args={[leader().nextReward?.level ?? ""]}
											/>
										</div>
									</div>
									<TicketBox class="flex-auto flex flex-row relative mt-1">
										<div class="img-tag-locked absolute left-0 top-5 flex flex-row items-start justify-start">
											<div class="img-lock2 size-8 mt-0\.5 ml-0\.5" />
										</div>
										<div class="flex flex-col items-center justify-center">
											<Icon
												class="size-19 m-4"
												name={`url('${leader().nextReward?.reward}')`}
												isUrl={true}
											/>
										</div>
										<div class="flex flex-col flex-auto ml-2">
											<div class="uppercase text-accent-5 font-title text-base mb-2">
												<L10n.Compose text={leader().nextReward?.title ?? ""} />
											</div>

											<L10n.Stylize
												class="flex-auto create-game-markup"
												text={rewardDesc() ?? leader().nextReward?.desc ?? ""}
											/>

											<Show when={rewardDesc()}>
												<div class="bg-primary-2 w-full -mr-2 h-0\.5" />
												<L10n.Stylize
													class="text-accent-5 text-sm my-1"
													text={leader().nextReward?.desc ?? ""}
												/>
											</Show>
										</div>
									</TicketBox>
								</Tooltip.Frame>
							</Tooltip.Content>
						</Tooltip>
					</Show>
				</div>
			</Show>
		</div>
	);
};

// MARK: CIV INFO
export const HubCivInfo: Component<HubLayout> = (props) => {
	const civModel = useCivSelectModelContext();
	const screenFlow = useScreenFlowContext();
	const ageContext = useAgeSelectModelContext();
	const choiceContext = useRecommendedChoiceModelContext();
	const leaderModel = useLeaderSelectModelContext();
	const isSmallScreen = useIsSmallScreen();

	const civID = createMemo(() => civModel.selectedCiv().civID);

	// TODO: These should be data driven somehow
	const civImage = createMemo(() => Locale.toLower(civID()).replace("civilization_", "bg_panel_"));

	const bgImage = createMemo(() => UI.getIconBLP(civID(), "BACKGROUND_VERT"));

	const activeAbility = createMemo(
		() =>
			civModel.selectedCiv().perAgeAbilities.find((a) => a.age == ageContext.selectedAge.type) ??
			civModel.selectedCiv().perAgeAbilities.find((a) => !a.age),
	);

	const filteredTraditions = createMemo(() => {
		return civModel.selectedCiv().traditions.filter((t) => t.age == ageContext.selectedAge.type);
	});

	const recommendation = createMemo(() => choiceContext.forLeader().get(civID()));

	const selectedCivTags = createMemo(() => civModel.selectedCiv().traits);

	const traditionTraitIcon = () => {
		return (
			<div
				class={`${isMobile() ? "absolute top-0 self-center" : ""} flex flex-row items-center justify-center create-game-hub-trait-icon-container`}
			>
				<Show when={filteredTraditions().length > 0}>
					<Tooltip>
						<Tooltip.Trigger>
							<AudioContextProvider segment="TraitIcon">
								<Activatable disableFocus={true}>
									<Icon
										name='url("blp:unlock_tradition")'
										class="size-9 create-game-hub-trait-icon"
									/>
								</Activatable>
							</AudioContextProvider>
						</Tooltip.Trigger>
						<Tooltip.Content>
							<Tooltip.Frame class="flex flex-col relative w-174 p-3">
								<div class="flex flex-row justify-center">
									<div class="text-base font-title uppercase text-tertiary-1 mb-2">
										<L10n.Compose text="LOC_UI_CREATE_GAME_TRADITIONS" />
									</div>
								</div>
								<TicketBox class="flex-auto flex flex-col mt-1">
									<ForWithSeparator
										separator={<div class="civ-details-card-divider-h mb-2 -ml-2 -mr-4 relative" />}
										each={filteredTraditions()}
									>
										{(item) => (
											<TraditionItem
												icon="unlock_tradition"
												civic={item.civic}
												name={item.title}
												description={item.text}
											/>
										)}
									</ForWithSeparator>
								</TicketBox>
							</Tooltip.Frame>
						</Tooltip.Content>
					</Tooltip>
				</Show>
			</div>
		);
	};

	return (
		<div class={`flex flex-col mx-1 ${props.class ?? ""}`}>
			<div class="uppercase font-body text-accent-2 text-sm mb-1">
				<L10n.Compose text="LOC_GENERIC_CIVILIZATION" />
			</div>
			<Tooltip
				showFiligrees={civID() != "RANDOM"}
				initialHPosition={
					civID() != "RANDOM" ? TooltipHorizontalPosition.RIGHT : TooltipHorizontalPosition.CENTER
				}
				initialVPosition={civID() != "RANDOM" ? TooltipVerticalPosition.CENTER : TooltipVerticalPosition.BOTTOM}
			>
				<Tooltip.Trigger>
					<Activatable
						class="create-game-hub-banner relative group"
						onActivate={() => screenFlow.activate("civ-select")}
					>
						<div class="absolute inset-0 flex flex-col items-center justify-end">
							<div class="absolute inset-0 img-unit-panelbox pointer-events-none" />
							<div
								class="absolute inset-0 bg-cover"
								style={{
									"background-image": `url('${bgImage()}')`,
									"background-position": "center center",
								}}
							/>
							<div
								class="absolute inset-0"
								style={{ background: `url('blp:${civImage()}.png')` }}
							/>
							<div class="create-game-hub-bottom-gradient absolute left-0 bottom-0" />
							<div class="absolute inset-0 w-full h-full border-2 border-secondary-3" />

							<Show when={civID() != "RANDOM"}>
								<Icon
									class="size-36 mb-10 relative"
									name={`url('${civModel.selectedCiv().icon}')`}
								/>
							</Show>
							<Show when={civID() == "RANDOM"}>
								<Icon
									class="size-22 mb-16 relative create-game-hub-random-icon"
									name={"LEADER_RANDOM"}
								/>
							</Show>
							<Show when={isMobile()}>{traditionTraitIcon()}</Show>
							<div class="absolute bottom-0\.5 w-full px-0\.5 flex justify-between">
								<For each={selectedCivTags()}>
									{(item) => (
										<div
											class="flex items-center justify-center size-12 ml-0\.5"
											style={{
												"background-image": "url(blp:hud_sub_circle_dis)",
												"background-repeat": "no-repeat",
												"background-size": "cover",
											}}
										>
											<AttributeIcon
												class="size-8 relative ml-0\.5 -mt-0\.5"
												attribute={item}
											/>
										</div>
									)}
								</For>
							</div>
							<div class="img-rollover-highlight absolute inset-0 opacity-0 group-focus\:opacity-100 group-hover\:opacity-100 group-pressed\:opacity-100 pointer-events-none" />
						</div>
					</Activatable>
				</Tooltip.Trigger>
				<Tooltip.Content>
					<Tooltip.Frame class={"flex flex-col relative p-3 " + (civID() != "RANDOM" ? "w-96" : "")}>
						<Show when={civID() == "RANDOM"}>
							<div class="flex-auto p-3 img-base-ticket-bg">
								<L10n.Compose text={civModel.selectedCiv().name} />
							</div>
						</Show>
						<Show when={civID() != "RANDOM"}>
							<div class="flex flex-row justify-center">
								<div class="uppercase text-tertiary-1 font-title uppercase">
									<L10n.Compose text={"LOC_UI_CREATE_GAME_CIVILIZATION_ABILITY"} />
								</div>
							</div>
							<div class="flex flex-row flex-wrap items-center justify-start gap-2 my-2">
								<For each={selectedCivTags()}>
									{(attribute) => (
										<div class="flex flex-row items-center justify-start self-center">
											<div class="create-game-civ-card-icon flex items-center justify-center gap-2">
												<Icon
													name={attribute
														.replace("LOC_TAG_TRAIT_", "ATTRIBUTE_")
														.replace("_NAME", "")}
													class={`relative size-8`}
													context="OUTLINE"
												/>
											</div>
											<div class="uppercase text-sm">
												<L10n.Compose text={attribute} />
											</div>
										</div>
									)}
								</For>
							</div>
							<TicketBox class="flex-auto flex flex-row relative mt-1">
								<div class="flex flex-col flex-auto ml-5">
									<div class="text-base font-title uppercase text-tertiary-1 mb-2">
										<L10n.Compose text={activeAbility()?.abilityTitle ?? ""} />
									</div>
									<div class="text-accent-5 text-sm">
										<L10n.Stylize
											class="create-game-markup"
											text={activeAbility()?.abilityText ?? ""}
										/>
									</div>
								</div>
							</TicketBox>

							<Show when={recommendation()?.reason && !isSmallScreen()}>
								<TicketBox class="flex flex-row items-center px-6 pt-4 pb-6">
									<Icon
										name={leaderModel.selectedLeader().icon}
										class="size-13"
									/>
									<L10n.Stylize
										class="flex-auto create-game-markup tight"
										text={recommendation()?.reason ?? ""}
									/>
								</TicketBox>
							</Show>
						</Show>
					</Tooltip.Frame>
				</Tooltip.Content>
			</Tooltip>
			<Show when={!isMobile()}>{traditionTraitIcon()}</Show>
		</div>
	);
};

// MARK: AGE INFO
export const HubAgeInfo: Component<HubLayout> = (props) => {
	const ageModel = useAgeSelectModelContext();
	const isAgeTransition = UI.isInGame();

	return (
		<div class={`flex flex-col mx-1 ${props.class ?? ""}`}>
			<div class="uppercase font-body text-accent-2 text-sm mb-1">
				<L10n.Compose text="LOC_UI_CREATE_GAME_AGE" />
			</div>
			<Popup.Trigger name="age-select">
				<Tooltip.Text text={ageModel.selectedAge.name}>
					<Activatable
						class="create-game-hub-banner relative group"
						disabled={isAgeTransition}
					>
						<div class="absolute inset-0 flex flex-col items-center justify-end">
							<div class="absolute inset-0 img-unit-panelbox pointer-events-none" />
							<div
								class="absolute inset-0"
								style={{
									"background-image": `url(${UI.getIconBLP(ageModel.selectedAge.type, "BACKGROUND_VERT")})`,
									"background-position": "center center",
									"background-size": "cover",
								}}
							/>
							<div class="create-game-hub-bottom-gradient absolute left-0 bottom-0" />
							<div class="absolute inset-0 w-full h-full border-2 border-secondary-3" />
							<div class="img-rollover-highlight absolute inset-0 opacity-0 group-focus\:opacity-100 group-hover\:opacity-100 group-pressed\:opacity-100 pointer-events-none" />

							<div
								class="flex items-center justify-center size-36 relative mb-10"
								style={{
									width: Layout.pixels(132),
									height: Layout.pixels(132),
									"background-image": "url(blp:hud_sub_circle_dis_128x128)",
									"background-repeat": "no-repeat",
									"background-size": "cover",
								}}
							>
								<Icon
									name={ageModel.selectedAge.icon}
									class="size-24 -bottom-px relative"
								/>
							</div>
						</div>
					</Activatable>
				</Tooltip.Text>
			</Popup.Trigger>
		</div>
	);
};

// MARK: MEMENTOS
export const HubMementos: Component<HubLayout> = (props) => {
	const mementosModel = useMementoSelectModelContext();

	return (
		<div class={`flex flex-col mx-1 ${props.class ?? ""}`}>
			<div class="uppercase font-body text-accent-2 text-sm mb-1 mx-2">
				<L10n.Compose text="LOC_UI_CREATE_GAME_MEMENTOS" />
			</div>
			<div class="flex flex-row justify-between">
				<For each={mementosModel.slots}>
					{(slot) => (
						<div class={`flex flex-col ${isMobile() ? "ml-2 mr-6" : "mx-2"} mb-2`}>
							<Tab.Trigger name="memento-select">
								<Tooltip.Text text={slot.currentMemento.name ?? ""}>
									<Activatable class="flex flex-row group  relative">
										<div class="flex items-center justify-center p-1 img-unit-panelbox relative create-game-hub-memento-box">
											<Icon
												name={`url('blp:memento_slot-base.png')`}
												class="absolute -top-4\.5 -left-4\.5 opacity-60 create-game-hub-memento-base"
											/>
											<div class="flex absolute inset-0 create-game-hub-memento-filigree" />
											<Icon
												name={`url('blp:${slot.currentMemento?.icon ?? ""}')`}
												isUrl={true}
												class="w-full h-full absolute inset-1"
											/>
											<div class="img-rollover-highlight absolute inset-0 opacity-0 group-focus\:opacity-100 group-hover\:opacity-100 group-pressed\:opacity-100 pointer-events-none" />
										</div>
									</Activatable>
								</Tooltip.Text>
							</Tab.Trigger>
						</div>
					)}
				</For>
			</div>
		</div>
	);
};

// MARK: GAME SETUP
export const HubGameSetup: Component<HubLayout> = (props) => {
	const screenFlow = useScreenFlowContext();

	// Most likely single player but handle edge case.
	const gameConfig = Configuration.getGame();
	let saveType = SaveTypes.SINGLE_PLAYER;
	if (gameConfig.isHotseat) {
		saveType = SaveTypes.HOTSEAT;
	} else if (gameConfig.isInternetMultiplayer) {
		saveType = SaveTypes.NETWORK_MULTIPLAYER;
	}

	function showSaveScreen() {
		ContextManager.push("screen-save-load", {
			singleton: true,
			createMouseGuard: true,
			attributes: {
				"menu-type": "save_config",
				"server-type": ServerType.SERVER_TYPE_NONE,
				"save-type": saveType,
			},
		});
	}

	function showLoadScreen() {
		ContextManager.push("screen-save-load", {
			singleton: true,
			createMouseGuard: true,
			attributes: {
				"menu-type": "load_config",
				"server-type": ServerType.SERVER_TYPE_NONE,
				"save-type": saveType,
			},
		});
	}

	const isAgeTransition = UI.isInGame();
	const isSmallScreen = useIsSmallScreen();

	return (
		<div class={`flex flex-col mx-1 ${isMobile() && isSmallScreen() ? "-mb-8" : "-mb-2"} ${props.class ?? ""}`}>
			<div class="uppercase font-body text-accent-2 text-sm mb-1 ml-2">
				<L10n.Compose text="LOC_UI_CREATE_GAME_GAME_SETUP" />
			</div>
			<div class="flex flex-row -mb-0\.5">
				<Tooltip.Text text={Locale.compose("LOC_UI_CREATE_GAME_ADJUST_GAME_SETTINGS")}>
					<Activatable
						class="flex flex-row group relative"
						onActivate={() => screenFlow.activate("game-setup")}
						disabled={isAgeTransition}
					>
						<div
							class={`flex items-center justify-center ${isMobile() ? "ml-2 mr-6 my-2" : "m-2"} p-1 img-unit-panelbox relative create-game-hub-setup-box`}
						>
							<Icon
								class="size-28"
								name={`url('blp:settings_adv_option_100x100')`}
							/>
							<div class="img-rollover-highlight absolute inset-0 opacity-0 group-focus\:opacity-100 group-hover\:opacity-100 group-pressed\:opacity-100 pointer-events-none" />
						</div>
					</Activatable>
				</Tooltip.Text>
				<div class="flex flex-col">
					<Tooltip.Text text={Locale.stylize("LOC_SAVE_LOAD_TITLE_SAVE_CONFIG")}>
						<Activatable
							class="flex flex-row group relative"
							onActivate={showSaveScreen}
							disabled={isAgeTransition}
						>
							<div class="flex items-center justify-center m-2 p-1 img-unit-panelbox relative create-game-hub-save-load-box">
								<Icon
									class="size-14"
									name="url('blp:save_config_noborder')"
								/>
								<div class="img-rollover-highlight absolute inset-0 opacity-0 group-focus\:opacity-100 group-hover\:opacity-100 group-pressed\:opacity-100 pointer-events-none" />
							</div>
						</Activatable>
					</Tooltip.Text>
					<Tooltip.Text text={Locale.stylize("LOC_SAVE_LOAD_TITLE_LOAD_CONFIG")}>
						<Activatable
							class="flex flex-row group relative"
							onActivate={showLoadScreen}
							disabled={isAgeTransition}
						>
							<div class="flex items-center justify-center m-2 p-1 img-unit-panelbox relative create-game-hub-save-load-box">
								<Icon
									class="size-14"
									name="url('blp:load_config_noborder')"
								/>

								<div class="img-rollover-highlight absolute inset-0 opacity-0 group-focus\:opacity-100 group-hover\:opacity-100 group-pressed\:opacity-100 pointer-events-none" />
							</div>
						</Activatable>
					</Tooltip.Text>
				</div>
			</div>
		</div>
	);
};

// MARK: OVERVIEW
