// MARK: HUB COMPONENT
export const CreateGameHubComponent: Component = () => {
	const ageModel = useAgeSelectModelContext();
	const civModel = useCivSelectModelContext();
	const leaderModel = useLeaderSelectModelContext();
	const flowContext = useScreenFlowContext();

	const isSmallScreen = useIsSmallScreen();
	return (
		<CreateGameHubLayout>
			<AudioContextProvider segment="CreateGameHub">
				<SpatialSlot
					name="create-game-hub-slot"
					class="flex flex-col absolute inset-0 items-start justify-center"
				>
					<div class="flex flex-row">
						<div
							class={
								isSmallScreen()
									? "w-14"
									: "create-game-hub-recap-panel flex flex-col uppercase items-start justify-center w-60"
							}
						>
							<Show when={!isSmallScreen()}>
								<Header class="ml-8 create-game-hub-recap-text uppercase font-black text-custom">
									{leaderModel.selectedLeader().name}
								</Header>
								<div class="create-game-hub-divider-half-line w-full my-5" />
								<Header class="ml-8 create-game-hub-recap-text uppercase font-black text-custom">
									{civModel.selectedCiv().name}
								</Header>
								<div class="create-game-hub-divider-half-line w-full my-5" />
								<Header class="ml-8 create-game-hub-recap-text uppercase font-black text-custom">
									{ageModel.selectedAge.name}
								</Header>
							</Show>
						</div>
						<div class={`flex flex-col w-fit ${isMobile() ? (isSmallScreen() ? "mb-6" : "mb-10") : ""}`}>
							<div
								class={`create-game-hub-divider-line top-line relative ${isMobile() ? "hidden" : ""}`}
							/>
							<div class={`flex flex-row ${isMobile() && !isSmallScreen() ? "mb-10" : ""}`}>
								<AudioContextProvider segment="HubLeaderInfo">
									<HubLeaderInfo />
								</AudioContextProvider>
								<AudioContextProvider segment="HubCivInfo">
									<HubCivInfo />
								</AudioContextProvider>
								<AudioContextProvider segment="HubAgeInfo">
									<HubAgeInfo />
								</AudioContextProvider>
								<div class="flex flex-col ml-8 justify-between create-game-hub-options">
									<AudioContextProvider segment="HubMementos">
										<HubMementos />
									</AudioContextProvider>
									<div class="flex-auto" />
									<AudioContextProvider segment="HubGameSetup">
										<HubGameSetup />
									</AudioContextProvider>
								</div>
							</div>
							<Show when={!isSmallScreen()}>
								<div class="flex flex-col relative">
									<div class="relative">
										<HubGameSetupOverview />
										{/* Reserved area for button area */}
										<div class="h-20" />
									</div>
								</div>
							</Show>
						</div>
					</div>
					<Show when={isSmallScreen()}>
						<div class="flex flex-col relative items-center self-center w-full">
							<div
								class="absolute top-0 bg-black opacity-50"
								style={{ left: "-100vw", right: "-100vw", bottom: "-100vh" }}
							/>
							<div class="relative w-full">
								<HubGameSetupOverview />
								{/* Reserved area for button area */}
								<div class={isMobile() ? "h-22" : "h-20"} />
							</div>
						</div>
					</Show>
					<div
						class={`absolute ${isMobile() && !isSmallScreen() ? "bottom-26" : "bottom-8"} create-game-hub-continue-button-container flex flex-row h-16 items-center justify-center`}
					>
						<div class="filigree-h4-left mt-3" />
						<HeroButton2
							class="flex items-center justify-center create-game-hub-continue-button"
							onActivate={() => flowContext.activateNext()}
						>
							<L10n.Compose text="LOC_UI_CREATE_GAME_START_GAME" />
						</HeroButton2>
						<div class="filigree-h4-right mt-3" />
					</div>
				</SpatialSlot>
			</AudioContextProvider>
		</CreateGameHubLayout>
	);
};

export const CreateGameHub = ComponentRegistry.register({
	name: "CreateGameHub",
	createInstance: CreateGameHubComponent,
	styles: [style],
});
